<span class="line"><span style="color:#C678DD;">                else</span><span style="color:#98C379;"> &quot;medium&quot;</span><span style="color:#C678DD;"> if</span><span style="color:#56B6C2;"> abs</span><span style="color:#ABB2BF;">(cohens_d) </span><span style="color:#56B6C2;">&lt;</span><span style="color:#D19A66;"> 0.8</span></span>
