<span class="line"><span style="color:#C678DD;">        if</span><span style="color:#ABB2BF;"> p_value </span><span style="color:#56B6C2;">&gt;=</span><span style="color:#E5C07B;"> self</span><span style="color:#ABB2BF;">.alpha:</span></span>
